   968→// GitCommitWithTrailerRemoved stages and commits files, simulating what happens when
   969→// a user removes the Entire-Checkpoint trailer during commit message editing.
   970→// This tests the opt-out behavior where removing the trailer skips condensation.
   971→func (env *TestEnv) GitCommitWithTrailerRemoved(message string, files ...string) {
   972→	env.T.Helper()
   973→
   974→	// Stage files using go-git
   975→	for _, file := range files {
   976→		env.GitAdd(file)
   977→	}
   978→
   979→	// Create a temp file for the commit message (prepare-commit-msg hook modifies this)
   980→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
   981→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
   982→		env.T.Fatalf("failed to write commit message file: %v", err)
   983→	}
   984→
   985→	// Run prepare-commit-msg hook using the shared binary
   986→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile)
   987→	prepCmd.Dir = env.RepoDir
   988→	if output, err := prepCmd.CombinedOutput(); err != nil {
   989→		env.T.Logf("prepare-commit-msg output: %s", output)
   990→	}
   991→
   992→	// Read the modified message (with trailer added by hook)
   993→	modifiedMsg, err := os.ReadFile(msgFile)
   994→	if err != nil {
   995→		env.T.Fatalf("failed to read modified commit message: %v", err)
   996→	}
   997→
   998→	// REMOVE the Entire-Checkpoint trailer (simulating user editing the message)
   999→	lines := strings.Split(string(modifiedMsg), "\n")
  1000→	var cleanedLines []string
  1001→	for _, line := range lines {
  1002→		// Skip the trailer and the comments about it
  1003→		if strings.HasPrefix(line, "Entire-Checkpoint:") {
  1004→			continue
  1005→		}
  1006→		if strings.Contains(line, "Remove the Entire-Checkpoint trailer") {
  1007→			continue
  1008→		}
  1009→		if strings.Contains(line, "trailer will be added to your next commit") {
  1010→			continue
  1011→		}
  1012→		cleanedLines = append(cleanedLines, line)
  1013→	}
  1014→	cleanedMsg := strings.TrimRight(strings.Join(cleanedLines, "\n"), "\n") + "\n"
  1015→
  1016→	// Create the commit using go-git with the cleaned message (no trailer)
  1017→	repo, err := git.PlainOpen(env.RepoDir)
  1018→	if err != nil {
  1019→		env.T.Fatalf("failed to open git repo: %v", err)
  1020→	}
  1021→
  1022→	worktree, err := repo.Worktree()
  1023→	if err != nil {
  1024→		env.T.Fatalf("failed to get worktree: %v", err)
  1025→	}
  1026→
  1027→	_, err = worktree.Commit(cleanedMsg, &git.CommitOptions{
  1028→		Author: &object.Signature{
  1029→			Name:  "Test User",
  1030→			Email: "test@example.com",
  1031→			When:  time.Now(),
  1032→		},
  1033→	})
  1034→	if err != nil {
  1035→		env.T.Fatalf("failed to commit: %v", err)
  1036→	}
  1037→
  1038→	// Run post-commit hook - since trailer was removed, no condensation should happen
  1039→	postCmd := exec.Command(getTestBinary(), "hooks", "git", "post-commit")
  1040→	postCmd.Dir = env.RepoDir
  1041→	if output, err := postCmd.CombinedOutput(); err != nil {
  1042→		env.T.Logf("post-commit output: %s", output)
  1043→	}
  1044→}
