  1163→// GetLatestCheckpointIDFromHistory walks backwards from HEAD on the active branch
  1164→// and returns the checkpoint ID from the first commit that has an Entire-Checkpoint trailer.
  1165→// This verifies that condensation actually happened (commit has trailer) without relying
  1166→// on timestamp-based matching.
  1167→func (env *TestEnv) GetLatestCheckpointIDFromHistory() string {
  1168→	env.T.Helper()
  1169→
  1170→	repo, err := git.PlainOpen(env.RepoDir)
  1171→	if err != nil {
