  1178→	}
  1179→
  1180→	commitIter, err := repo.Log(&git.LogOptions{From: head.Hash()})
  1181→	if err != nil {
  1182→		env.T.Fatalf("failed to iterate commits: %v", err)
  1183→	}
  1184→
  1185→	var checkpointID string
  1186→	//nolint:errcheck // ForEach callback handles errors
  1187→	commitIter.ForEach(func(c *object.Commit) error {
  1188→		if cpID, found := trailers.ParseCheckpoint(c.Message); found {
  1189→			checkpointID = cpID.String()
  1190→			return errors.New("stop iteration") // Found it, stop
  1191→		}
  1192→		return nil
  1193→	})
  1194→
  1195→	if checkpointID == "" {
  1196→		env.T.Fatalf("no commit with Entire-Checkpoint trailer found in history")
  1197→	}
  1198→
  1199→	return checkpointID
  1200→}
  1201→
  1202→// ShardedCheckpointPath returns the sharded path for a checkpoint ID.
  1203→// Format: <id[:2]>/<id[2:]>
  1204→// Delegates to id.CheckpointID.Path() for consistency.
  1205→func ShardedCheckpointPath(checkpointID string) string {
  1206→	return id.CheckpointID(checkpointID).Path()
  1207→}
  1208→
  1209→// SessionFilePath returns the path to a session file within a checkpoint.
  1210→// Session files are stored in numbered subdirectories using 0-based indexing (e.g., 0/full.jsonl).
  1211→// This function constructs the path for the first (default) session.
  1212→func SessionFilePath(checkpointID string, fileName string) string {
  1213→	return id.CheckpointID(checkpointID).Path() + "/0/" + fileName
  1214→}
  1215→
  1216→// CheckpointSummaryPath returns the path to the root metadata.json (CheckpointSummary) for a checkpoint.
  1217→func CheckpointSummaryPath(checkpointID string) string {
  1218→	return id.CheckpointID(checkpointID).Path() + "/" + paths.MetadataFileName
  1219→}
  1220→
  1221→// SessionMetadataPath returns the path to the session-level metadata.json for a checkpoint.
  1222→func SessionMetadataPath(checkpointID string) string {
  1223→	return SessionFilePath(checkpointID, paths.MetadataFileName)
  1224→}
  1225→
  1226→func findModuleRoot() string {
  1227→	// Start from this source file's location and walk up to find go.mod
  1228→	_, thisFile, _, ok := runtime.Caller(0)
  1229→	if !ok {
  1230→		panic("failed to get current file path via runtime.Caller")
  1231→	}
  1232→	dir := filepath.Dir(thisFile)
  1233→
  1234→	for {
  1235→		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
  1236→			return dir
  1237→		}
  1238→		parent := filepath.Dir(dir)
  1239→		if parent == dir {
  1240→			panic("could not find go.mod starting from " + thisFile)
  1241→		}
  1242→		dir = parent
  1243→	}
  1244→}
