// TestPrepareCommitMsg_MessageSourceRestoresPendingCheckpointID verifies that when
// using `git commit -m` or `git commit --amend -m` (source="message") with a
// PendingCheckpointID set in session state, the trailer is automatically added
// WITHOUT prompting via /dev/tty. This is the isRestoringExisting=true path.
//
// This is critical for non-interactive environments (e.g., Claude doing commits)
// where /dev/tty is unavailable and askConfirmTTY would silently return false,
// dropping the trailer.
func TestPrepareCommitMsg_MessageSourceRestoresPendingCheckpointID(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	s := &ManualCommitStrategy{}

	sessionID := "test-session-message-restore"
	err := s.InitializeSession(sessionID, "Claude Code", "")
	require.NoError(t, err)

	// Create content on the shadow branch so filterSessionsWithNewContent finds it
	createShadowBranchWithTranscript(t, dir, sessionID)

	// Set the session to ACTIVE_COMMITTED with a PendingCheckpointID
	// This simulates the state after condensation during a mid-session commit
	state, err := s.loadSessionState(sessionID)
	require.NoError(t, err)
	require.NotNil(t, state)
	state.Phase = session.PhaseActiveCommitted
	state.PendingCheckpointID = "aabb11223344"
	state.StepCount = 1
	err = s.saveSessionState(state)
	require.NoError(t, err)

	// Write a commit message file (simulating git commit --amend -m "new message")
	commitMsgFile := filepath.Join(t.TempDir(), "COMMIT_EDITMSG")
	msg := "Amended message via -m flag\n"
	require.NoError(t, os.WriteFile(commitMsgFile, []byte(msg), 0o644))

	// Call PrepareCommitMsg with source="message" (git commit -m or --amend -m)
	// This would normally trigger askConfirmTTY, but with PendingCheckpointID set,
	// isRestoringExisting=true should skip the prompt and add the trailer directly.
	err = s.PrepareCommitMsg(commitMsgFile, "message")
	require.NoError(t, err)

	// Read the file back - trailer should be auto-added from PendingCheckpointID
	content, err := os.ReadFile(commitMsgFile)
	require.NoError(t, err)

	cpID, found := trailers.ParseCheckpoint(string(content))
	assert.True(t, found,
		"trailer should be auto-added for source=\"message\" when PendingCheckpointID is set")
	assert.Equal(t, "aabb11223344", cpID.String(),
		"trailer should use PendingCheckpointID value without requiring TTY confirmation")
}

